import os,json,subprocess
from pathlib import Path
aliases={"/root/iptvpn_bot":"/srv/projects/iptvpn-bot","/etc/iptvpn-bot":"/srv/projects/iptvpn-bot/config","/root/project-secrets/iptvpn_bot":"/srv/projects/iptvpn-bot/private"}
out={"aliases":{},"active_refs":{},"private_config_ref_count":{},"pm2_dump_ref_count":{},"active_process_ref_count":{}}
for old,target in aliases.items():
 p=Path(old);out["aliases"][old]={"symlink":p.is_symlink(),"correct_target":p.is_symlink() and p.resolve(strict=False)==Path(target)}
for old in aliases:out["active_refs"][old]=[]
checked=0
for base in ("/etc/systemd/system","/etc/nginx","/etc/cron.d","/usr/local/bin","/usr/local/sbin","/srv/projects/iptvpn-bot"):
 root=Path(base)
 if not root.is_dir():continue
 for cur,dirs,files in os.walk(root,followlinks=False):
  depth=len(Path(cur).relative_to(root).parts)
  if depth>4:dirs[:]=[];continue
  dirs[:]=[x for x in dirs if x not in ("archive",".git","node_modules",".venv","tools","data","logs","private","config","__pycache__", ".pm2")]
  for n in files:
   p=Path(cur)/n
   try:
    if p.is_symlink() or not p.is_file() or p.stat().st_size>150000:continue
    checked+=1
    b=p.read_bytes()
    for old in aliases:
     if old.encode() in b:out["active_refs"][old].append(str(p))
   except OSError:pass
for base in (Path("/srv/projects/iptvpn-bot/config"),Path("/srv/projects/iptvpn-bot/private")):
 if base.is_dir():
  for p in base.rglob("*"):
   try:
    if p.is_file() and not p.is_symlink() and p.stat().st_size<200000:
     b=p.read_bytes()
     for old in aliases:out["private_config_ref_count"][old]=out["private_config_ref_count"].get(old,0)+b.count(old.encode())
   except OSError:pass
for path in (Path("/root/.pm2/dump.pm2"),Path("/srv/projects/iptvpn-bot/.pm2/dump.pm2")):
 if path.is_file():
  b=path.read_bytes();out["pm2_dump_ref_count"][str(path)]={old:b.count(old.encode()) for old in aliases}
for proc in Path("/proc").iterdir():
 if not proc.name.isdecimal():continue
 try:
  b=(proc/"environ").read_bytes()
  for old in aliases:
   if old.encode() in b:out["active_process_ref_count"][old]=out["active_process_ref_count"].get(old,0)+1
 except (OSError,PermissionError):pass
out["files_scanned"]=checked
print(json.dumps(out,sort_keys=True))
